import hashlib,json,pathlib,itertools
root=pathlib.Path('/reference/reference-semantics')
files=sorted(p for p in root.rglob('*') if p.is_file())
rels=[p.relative_to(root).as_posix() for p in files]
contents=[p.read_bytes() for p in files]
digests=[hashlib.sha256(b).hexdigest() for b in contents]
targets={'content':'1de6d5f51876cf9d0f4449a78f077f8b127a14add0504d5060da680fc5a443de','manifest':'4e06397a1c5a2c7be4f6cc3f61490d87805523b8c9d3c1a0ecd8e1d6bde3789f'}
def chk(name,b):
 h=hashlib.sha256(b).hexdigest()
 if h in targets.values(): print('MATCH',name,h)
 #else: print(name,h)
for sep in [b'',b'\n',b'\0',b'  ']:
 for between in [b'',b'\n',b'\0',b' ']:
  chk(f'rel{sep!r}content_between{between!r}',between.join(r.encode()+sep+c for r,c in zip(rels,contents)))
  chk(f'rel{sep!r}digest_between{between!r}',between.join(r.encode()+sep+d.encode() for r,d in zip(rels,digests)))
  chk(f'digest{sep!r}rel_between{between!r}',between.join(d.encode()+sep+r.encode() for r,d in zip(rels,digests)))
objs=[]
objs.append(('dict_digest',{r:d for r,d in zip(rels,digests)}))
objs.append(('dict_content',{r:c.decode() for r,c in zip(rels,contents)}))
objs.append(('list_pairs_digest',list(zip(rels,digests))))
objs.append(('list_objs_digest',[{'path':r,'sha256':d} for r,d in zip(rels,digests)]))
for name,obj in objs:
 for indent in [None,0,2,4]:
  for sort in [False,True]:
   for seps in [None,(',',':'),(', ', ': ')]:
    s=json.dumps(obj,indent=indent,sort_keys=sort,separators=seps).encode()
    for trail in [b'',b'\n']:
     chk(f'{name}-{indent}-{sort}-{seps}-{trail!r}',s+trail)
print('done')
